// 收到店內辨識程式送來的狀態 → 檢查格式 → 產生 status.json
const TOKEN = 'TOKEN_PLACEHOLDER';
const body = $input.first().json.body || {};
if (body.token !== TOKEN) throw new Error('token 錯誤，拒絕上傳');
const s = body.status || {};
if (s.connected !== true || !Number.isInteger(s.count) || s.count < 0 || s.count > 99 || !s.updatedAt) throw new Error('狀態格式錯誤');
const status = {
  connected: true, open: s.open !== false, count: s.count,
  machines: (s.machines || []).slice(0, 4).map(m => ({ name: String(m.name || '洗車機').slice(0, 20), inUse: m.inUse === true })),
  updatedAt: String(s.updatedAt).slice(0, 40),
};
return [{ json: status, binary: { data: { data: Buffer.from(JSON.stringify(status), 'utf8').toString('base64'),
  mimeType: 'application/json', fileName: 'status.json', fileExtension: 'json' } } }];
